insert into public.updates (event_date, kind_en, kind_hi, title_en, title_hi, summary_en, summary_hi, place_en, place_hi, image_url, sort_order) values
('2026-08-18','Event','कार्यक्रम','Addressed the extended State Executive meeting','विस्तारित प्रदेश कार्यसमिति बैठक को संबोधित','Addressed the extended State Executive meeting and Yuva Samvad in Andhra Pradesh.','आंध्र प्रदेश में विस्तारित प्रदेश कार्यसमिति बैठक और युवा संवाद को संबोधित किया।','Visakhapatnam, Andhra Pradesh','विशाखापत्तनम, आंध्र प्रदेश','https://www.nitinnabin.com/images/albums/album-3.jpg',1),
('2026-08-17','Public event','सार्वजनिक कार्यक्रम','Attended the launch of M. Venkaiah Naidu''s biography','एम. वेंकैया नायडू की जीवनी के विमोचन में सम्मिलित','Present at the launch of the biography of former Vice President M. Venkaiah Naidu.','पूर्व उपराष्ट्रपति एम. वेंकैया नायडू की जीवनी के विमोचन कार्यक्रम में उपस्थित।','New Delhi','नई दिल्ली','https://www.nitinnabin.com/images/albums/album-4.jpg',2),
('2026-08-12','Event','कार्यक्रम','Joined the Tiranga Yatra','तिरंगा यात्रा कार्यक्रम में सम्मिलित','Took part in the Tiranga Yatra held in the capital.','राजधानी में आयोजित तिरंगा यात्रा कार्यक्रम में भाग लिया।','New Delhi','नई दिल्ली','https://www.nitinnabin.com/images/albums/album-5.jpg',3),
('2026-04-06','Statement','वक्तव्य','Addressed workers on the party''s 47th Foundation Day','पार्टी के 47वें स्थापना दिवस पर कार्यकर्ताओं को संबोधित','Said the party''s strength rests on the dedication of its lakhs of workers, and paid tribute to past national presidents. Noted the party was founded in 1980.','कहा कि पार्टी की शक्ति उसके लाखों कार्यकर्ताओं के समर्पण और निष्ठा पर टिकी है, और पूर्व राष्ट्रीय अध्यक्षों को श्रद्धांजलि दी।','New Delhi','नई दिल्ली','https://www.nitinnabin.com/images/albums/album-6.jpg',4);
insert into public.milestones (year, kind_en, kind_hi, title_en, title_hi, place_en, place_hi, body_en, body_hi, record_en, record_hi, sort_order) values
('2006','Election','चुनाव','Elected to the Bihar Assembly at twenty-six','छब्बीस वर्ष की आयु में बिहार विधानसभा के लिए निर्वाचित','Patna West · Bihar','पटना पश्चिम · बिहार','Fielded in the by-election for Patna West, left vacant by the passing of his father, four-term MLA Nabin Kishore Prasad Sinha. Won by roughly 60,000 votes.','उसी क्षेत्र से चार बार विधायक रहे उनके पिता नवीन किशोर प्रसाद सिन्हा के निधन से रिक्त हुई पटना पश्चिम सीट पर उपचुनाव में उम्मीदवार बनाए गए। लगभग 60,000 मतों के अंतर से जीत दर्ज की।','Term: 11 May 2006 – 24 Nov 2010','कार्यकाल: 11 मई 2006 – 24 नव 2010',1),
('2010','Election','चुनाव','First win from Bankipur','बांकीपुर से पहली जीत','Bankipur · Patna','बांकीपुर · पटना','After delimitation, Patna West was reconstituted as Bankipur. Contested the new seat and won.','परिसीमन के बाद पटना पश्चिम का पुनर्गठन बांकीपुर के रूप में हुआ। नई सीट से चुनाव लड़ा और जीता।','Term: 2010 – 2015','कार्यकाल: 2010 – 2015',2),
('2015','Election','चुनाव','Third Assembly term','तीसरा विधानसभा कार्यकाल','Bankipur · Patna','बांकीपुर · पटना','Elected for a third consecutive term from Bankipur.','बांकीपुर से लगातार तीसरी बार निर्वाचित।','Term: 2015 – 2020','कार्यकाल: 2015 – 2020',3),
('2019','Organisation','संगठन','Yuva Morcha leadership','युवा मोर्चा नेतृत्व','Bihar · National','बिहार · राष्ट्रीय','Served as Bihar state president of the BJYM, later national general secretary of the Yuva Morcha.','भाजयुमो के बिहार प्रदेश अध्यक्ष, फिर युवा मोर्चा के राष्ट्रीय महामंत्री।','Organisational post','संगठनात्मक पद',4),
('2020','Election','चुनाव','Bankipur, fourth term','बांकीपुर, चौथा कार्यकाल','Bankipur · Patna','बांकीपुर · पटना','Won a fourth consecutive term by a margin of 39,036 votes.','39,036 मतों के अंतर से लगातार चौथी जीत।','Term: 2020 – 2025','कार्यकाल: 2020 – 2025',5),
('2021','Governance','शासन','Joined the cabinet','मंत्रिमंडल में प्रवेश','Government of Bihar','बिहार सरकार','Sworn in as Minister for Road Construction in the Nitish Kumar government.','नीतीश कुमार सरकार में पथ निर्माण मंत्री के रूप में शपथ।','Feb 2021 – Aug 2022','फ़र 2021 – अग 2022',6),
('2023','Organisation','संगठन','Chhattisgarh campaign','छत्तीसगढ़ अभियान','Chhattisgarh','छत्तीसगढ़','Appointed election in-charge for the Chhattisgarh Assembly election and led the party campaign.','छत्तीसगढ़ विधानसभा चुनाव के प्रभारी नियुक्त; पार्टी अभियान का नेतृत्व।','Election in-charge, 2023','चुनाव प्रभारी, 2023',7),
('2024','Governance','शासन','Back in cabinet','मंत्रिमंडल में वापसी','Government of Bihar','बिहार सरकार','Returned as Minister for Law & Justice, then took Urban Development & Housing and Road Construction.','विधि एवं न्याय मंत्री के रूप में वापसी, फिर नगर विकास एवं आवास तथा पथ निर्माण विभाग।','Mar 2024 – Dec 2025','मार्च 2024 – दिस 2025',8),
('2025','Election · National','चुनाव · राष्ट्रीय','Fifth term; Working President','पाँचवाँ कार्यकाल; कार्यकारी अध्यक्ष','Bankipur · New Delhi','बांकीपुर · नई दिल्ली','Polled 98,299 votes, winning by 51,936. In December the Parliamentary Board appointed him National Working President; he resigned from the Bihar cabinet.','98,299 मत, 51,936 के अंतर से जीत। दिसंबर में संसदीय बोर्ड ने राष्ट्रीय कार्यकारी अध्यक्ष नियुक्त किया; बिहार मंत्रिमंडल से इस्तीफा।','Dec 2025 – Jan 2026','दिस 2025 – जन 2026',9),
('2026','National','राष्ट्रीय','Elected National President','राष्ट्रीय अध्यक्ष निर्वाचित','Party headquarters · New Delhi','पार्टी मुख्यालय · नई दिल्ली','Elected unopposed on 20 January 2026 — the youngest to hold the post and the first from Bihar.','20 जनवरी 2026 को निर्विरोध निर्वाचित — इस पद पर सबसे युवा और बिहार से पहले।','National President, since 20 Jan 2026','राष्ट्रीय अध्यक्ष, 20 जन 2026 से',10);
