insert into public.social_posts (platform, image_url, text_en, text_hi, label_en, label_hi, when_en, when_hi, stats, sort_order) values
('fb','https://www.nitinnabin.com/images/portrait-bio.avif','Joined the extended State Executive meeting and Yuva Samvad in Visakhapatnam, Andhra Pradesh, and interacted with energetic party workers.','आंध्र प्रदेश के विशाखापत्तनम में आयोजित विस्तारित प्रदेश कार्यसमिति बैठक व युवा संवाद में सम्मिलित होकर ऊर्जावान कार्यकर्ताओं से संवाद किया।','Facebook Video','Facebook Video','18 Aug 2026','18 अग 2026','👍 4.8K',1),
('fb','https://www.nitinnabin.com/images/portrait-fields.avif','Took part in the Tiranga Yatra in New Delhi. Renewed the Nation First pledge with lakhs of workers.','राजधानी नई दिल्ली में आयोजित तिरंगा यात्रा कार्यक्रम में भाग लिया। लाखों कार्यकर्ताओं के साथ राष्ट्र प्रथम का संकल्प दोहराया।','Tiranga Yatra','तिरंगा यात्रा','12 Aug 2026','12 अग 2026','👍 6.5K',2),
('fb','https://www.nitinnabin.com/images/portrait-contact.avif','Attended the launch of the inspiring biography of former Vice President Shri M. Venkaiah Naidu. His public life is a guide for all of us.','पूर्व उपराष्ट्रपति श्री एम. वेंकैया नायडू जी की प्रेरक जीवनी के विमोचन कार्यक्रम में सहभागिता। उनका सार्वजनिक जीवन हम सभी के लिए पथप्रदर्शक है।','New Delhi','नई दिल्ली','17 Aug 2026','17 अग 2026','👍 3.9K',3),
('x','https://www.nitinnabin.com/images/portrait-fields.avif','Heartfelt greetings to every dedicated karyakarta on the party''s 47th Foundation Day. The party''s strength rests on the dedication and commitment of lakhs of workers. #BJPFoundationDay','पार्टी के 47वें स्थापना दिवस पर समस्त कर्मठ कार्यकर्ताओं को हार्दिक बधाई। पार्टी की शक्ति लाखों कार्यकर्ताओं के समर्पण और निष्ठा पर टिकी है। #BJPFoundationDay','Foundation Day message','स्थापना दिवस संदेश','06 Apr 2026','06 अप्रैल 2026','🔁 1.8K ❤️ 9.4K',1),
('x','https://www.nitinnabin.com/images/portrait-bio.avif','Organisational meeting with senior office-bearers of the Gujarat unit at Kamalam, Gandhinagar. Urged workers to stay active with new goals.','कमलम, गांधीनगर में गुजरात प्रदेश संगठन के वरिष्ठ पदाधिकारियों के साथ सांगठनिक बैठक। कार्यकर्ताओं को नए लक्ष्यों के साथ निरंतर सक्रिय रहने का आह्वान किया।','Gandhinagar, Gujarat','गांधीनगर, गुजरात प्रवास','21 Feb 2026','21 फ़र 2026','🔁 2.3K ❤️ 11.8K',2),
('x','https://www.nitinnabin.com/images/hero-bg.jpg','First official visit to West Bengal: state core team meeting in Durgapur and the Bardhaman division workers'' convention. The enthusiasm is unprecedented.','पश्चिम बंगाल का पहला आधिकारिक दौरा: दुर्गापुर में प्रदेश कोर टीम बैठक एवं बर्दवान संभाग कार्यकर्ता सम्मेलन में भाग लिया। कार्यकर्ताओं का उत्साह अभूतपूर्व है।','West Bengal visit','पश्चिम बंगाल प्रवास','27 Jan 2026','27 जन 2026','🔁 1.9K ❤️ 8.6K',3),
('ig','https://www.nitinnabin.com/images/portrait-bio.avif','Shared thoughts with young people at the Yuva Samvad in Visakhapatnam. Innovation and service to the nation are India''s future. ✨','विशाखापत्तनम में आयोजित युवा संवाद में युवाओं के साथ प्रेरक विचार साझा किए। नवाचार और राष्ट्रसेवा ही भारत का भविष्य है। ✨','Visakhapatnam • Yuva Samvad','विशाखापत्तनम • युवा संवाद','3 days ago','3 दिन पहले','❤️ 14.8K · 💬 482',1),
('ig','https://www.nitinnabin.com/images/portrait-fields.avif','Sangathan Parv: the energy and dedication of karyakartas is the party''s real capital. Service is organisation.','संगठन पर्व: कार्यकर्ताओं की ऊर्जा और समर्पण ही भारतीय जनता पार्टी की वास्तविक पूंजी है। सेवा ही संगठन।','Kamalam • Organisation review','कमलम • संगठन समीक्षा','5 days ago','5 दिन पहले','❤️ 19.2K · 💬 640',2),
('ig','https://www.nitinnabin.com/images/portrait-contact.avif','Warm interaction with workers and senior office-bearers at the central office in New Delhi.','नई दिल्ली स्थित केंद्रीय कार्यालय में कार्यकर्ताओं एवं वरिष्ठ पदाधिकारियों से आत्मीय संवाद।','New Delhi • Central office','नई दिल्ली • केंद्रीय कार्यालय','1 week ago','1 सप्ताह पहले','❤️ 12.1K · 💬 310',3),
('yt','https://www.nitinnabin.com/images/portrait-bio.avif','Taking charge: historic address as National President | New Delhi','कार्यभार ग्रहण: राष्ट्रीय अध्यक्ष के रूप में ऐतिहासिक संबोधन | नई दिल्ली','18:42','18:42','1 month ago','1 माह पहले','94K views',1),
('yt','https://www.nitinnabin.com/images/portrait-fields.avif','Inspiring message to party workers on the 47th Foundation Day','47वें स्थापना दिवस पर पार्टी कार्यकर्ताओं को प्रेरणादायी संदेश','14:15','14:15','2 weeks ago','2 सप्ताह पहले','128K views',2),
('yt','https://www.nitinnabin.com/images/portrait-contact.avif','Extended State Executive meeting: key organisational address','विस्तारित प्रदेश कार्यसमिति बैठक: महत्वपूर्ण सांगठनिक संबोधन','22:08','22:08','3 weeks ago','3 सप्ताह पहले','76K views',3);
